import"./chunk-7CGTOI24.js";var e={slug:"review-hollow-knight-silksong",title:"Review: Hollow Knight: Silksong \xE9 dif\xEDcil, generoso e lindo de doer",dek:"Um ano depois do lan\xE7amento, revisitamos a aventura de Hornet em Pharloom. Silksong cobra muito do jogador e devolve ainda mais.",section:"games",kind:"review",tags:["Indie","Metroidvania","Nintendo","PlayStation","Xbox"],date:"2026-10-22",hero:{ref:"game:115289",pick:0,alt:"Hornet, protagonista de Hollow Knight: Silksong, em arte oficial"},score:9,verdict:{summary:"Uma continua\xE7\xE3o que n\xE3o tem medo de ser maior e mais exigente que o original. Quem aceita o desafio encontra um dos melhores jogos de plataforma e explora\xE7\xE3o da d\xE9cada.",good:["Movimenta\xE7\xE3o de Hornet r\xE1pida e precisa","Dire\xE7\xE3o de arte e trilha sonora impec\xE1veis","Mundo denso, cheio de segredos que recompensam a curiosidade"],bad:["Picos de dificuldade que podem afastar iniciantes","Algumas caminhadas longas at\xE9 chefes depois de cada derrota"]},body:[{p:"A espera por *Hollow Knight: Silksong* virou piada na internet durante anos. Quando o jogo da Team Cherry finalmente saiu, em 4 de setembro de 2025, chegou de uma vez a PC, PlayStation 4 e 5, Xbox One e Series, Switch e Switch 2. Mais de um ano depois, com a poeira baixada, d\xE1 para avaliar com calma: valeu a espera, e com folga."},{ficha:"game:115289"},{h2:"Hornet n\xE3o \xE9 o Cavaleiro"},{p:"A protagonista agora \xE9 Hornet, a guerreira que enfrentamos e ajudamos no primeiro jogo. Ela \xE9 capturada e levada a Pharloom, um reino governado por seda e can\xE7\xE3o, e precisa escalar at\xE9 a cidadela no topo. A diferen\xE7a aparece no primeiro minuto: Hornet \xE9 mais \xE1gil, salta mais alto, avan\xE7a em diagonal e se agarra a bordas com naturalidade."},{p:"Essa leveza muda o ritmo de tudo. O combate fica mais agressivo, as plataformas pedem precis\xE3o maior, e o jogo confia que voc\xEA vai aprender r\xE1pido. A cura tamb\xE9m mudou: em vez de recuperar uma m\xE1scara por vez, Hornet usa a seda acumulada para curar v\xE1rias de uma s\xF3 vez, o que exige escolher o momento certo no meio da luta."},{img:"game:115289",pick:4,caption:"Pharloom tem biomas muito diferentes entre si. Imagem de divulga\xE7\xE3o."},{h2:"Um mundo que esconde coisas"},{p:"Pharloom \xE9 enorme e quase sempre recompensa quem sai do caminho principal. Ferramentas novas, atalhos, miss\xF5es de personagens secund\xE1rios e bras\xF5es que alteram o estilo de luta aparecem em cantos que parecem vazios. \xC9 o tipo de design que transforma o mapa em conversa entre amigos: cada um encontrou uma coisa em um lugar diferente."},{quote:"Silksong n\xE3o pede desculpas pela dificuldade. Ele confia em voc\xEA, e \xE9 justamente essa confian\xE7a que torna cada vit\xF3ria t\xE3o boa."},{h2:"A dificuldade \xE9 o assunto"},{p:"N\xE3o d\xE1 para falar de *Silksong* sem falar de dificuldade. Alguns chefes s\xE3o duros de verdade, e certas \xE1reas punem erros com um dano maior do que o primeiro jogo aplicava. Em alguns trechos, a caminhada de volta at\xE9 um chefe depois de morrer cansa mais do que a luta em si."},{p:"Ainda assim, raramente o jogo parece injusto. Os padr\xF5es dos inimigos s\xE3o leg\xEDveis, a resposta dos controles \xE9 imediata e quase toda derrota ensina alguma coisa. Para quem nunca jogou um metroidvania, a recomenda\xE7\xE3o \xE9 come\xE7ar pelo *Hollow Knight* original. Para quem j\xE1 passou por Hallownest, *Silksong* \xE9 obrigat\xF3rio."},{h2:"Arte e som"},{p:"O desenho \xE0 m\xE3o continua lindo, agora com mais cor e mais variedade de cen\xE1rios. A trilha acompanha cada regi\xE3o com personalidade pr\xF3pria, e o som do combate, seco e met\xE1lico, ajuda a ler o que est\xE1 acontecendo na tela. Em um Switch 2 no modo port\xE1til ou em uma TV grande, o jogo impressiona do mesmo jeito."},{h2:"Veredito"},{p:"*Silksong* \xE9 um jogo que faz poucas concess\xF5es e acerta quase todas as escolhas. Exige paci\xEAncia, mas devolve cada minuto em descobertas e momentos de pura satisfa\xE7\xE3o. Nota 9, com a ressalva honesta de que ele n\xE3o \xE9 para todo mundo."}]};var o={source:"TMDB + IGDB",updatedAt:"2026-11-10",calendar:[],games:{115289:{id:115289,name:"Hollow Knight: Silksong",type:"Jogo principal",cover:"cobebu",shots:["sc63aa","sc63a9","sc63ab","sc63a8","sc63ac","sc63a7"],arts:["ar4prh","ar4pri","ar4prf","ar41sh"],genres:["Plataforma","Aventura","Indie","A\xE7\xE3o"],modes:["Single player"],devs:["Team Cherry"],pubs:["Team Cherry"],released:"2025-09-04",releases:{"Switch 2":"2025-09-04",PC:"2025-09-04","Xbox Series X|S":"2025-09-04",Switch:"2025-09-04",PS4:"2025-09-04",PS5:"2025-09-04","Xbox One":"2025-09-04"},classInd:"12"}},movies:{},tv:{}};export{o as media,e as post};
